const N = parseInt(readline());
for (let i = 0; i < N; i++) {
    const T = readline();
    const cut = T.lastIndexOf(' ');
    const msg = T.slice(0, cut);
    const D = parseInt(T.slice(cut + 1));
    const letters = (msg.match(/[A-Za-z]/g) || []).length;

    console.log(letters % 10 === D ? 'AUTHENTIC' : 'FORGED');
}5
